head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var options = {
        id: "111",
        popupName: "",
        type: "wframePopup", // iframePopup, wframePopup, browserPopup
        width: "520px",
        height: "300px",
        top: "140px",
        left: "500px",
        popupName: '',
        modal: true,
        dataObject: {} // litewindow 에서 사용 가능 기능
    };
    $w.openPopup("gridview_context_menu_WEFF-353_(WSQ-3775)_popup.xml", options);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
